async function handleTimelineAction(button){
  const data=button.dataset;let action=null;
  if(data.timelineReturn)action=()=>timelineReturnTo(data.timelineReturn);
  else if(data.timelineRemoveEvidence)action=()=>{const context=timelineCurrentContext();timelineSelection(context).delete(data.timelineRemoveEvidence);for(const field of $$('[data-timeline-evidence]:checked',context.root))if(field.dataset.timelineEvidence===data.timelineRemoveEvidence)field.checked=false;timelineUpdateSelection(context);};
  else if(Object.hasOwn(data,'timelineClearEvidence'))action=()=>{const context=timelineCurrentContext();timelineSelection(context).clear();for(const field of $$('[data-timeline-evidence]:checked',context.root))field.checked=false;timelineUpdateSelection(context);};
  else if(Object.hasOwn(data,'timelineDismissReceipt'))action=()=>{const context=timelineCurrentContext();delete context.justSaved;button.closest('.timeline-save-receipt')?.remove();};
  else if(data.timelineOpenSource&&state.detail?.type==='timeline')action=()=>timelineOpenSource(data.timelineOpenSource,data.timelineSourceId);
  else if(data.timelineContext)action=()=>timelineOpenContext(data.timelineContext,(data.customerTimeline||data.contactTimeline)?{customerId:data.customerTimeline,contactId:data.contactTimeline,opportunityId:data.timelineProject}:null,button);
  else if(data.customerTimeline||data.contactTimeline)action=()=>openCustomerTimeline({customerId:data.customerTimeline,contactId:data.contactTimeline,opportunityId:data.timelineProject});
  else if(data.timelineEvent)action=()=>timelineOpenEvent(data.timelineEvent,button);
  else if(Object.hasOwn(data,'timelineCapture'))action=()=>timelineOpenCapture(timelineCurrentContext());
  else if(Object.hasOwn(data,'timelineRefresh'))action=()=>timelineLoad(timelineCurrentContext());
  else if(data.timelinePage)action=()=>timelineLoad(timelineCurrentContext(),{page:Number(data.timelinePage)});
  else if(Object.hasOwn(data,'timelineClearFilter'))action=()=>{const context=timelineCurrentContext();context.filters={...context.filters,kind:'',q:'',page:1};return timelineLoad(context);};
  else if(Object.hasOwn(data,'timelineDiscuss'))action=()=>{const context=timelineCurrentContext(),keys=data.timelineDiscuss?[data.timelineDiscuss]:[...timelineSelection(context).keys()];return timelineDiscuss(context,keys);};
  if(!action)return false;await mutateButton(button,action);return true;
}
