  if(event.target.hasAttribute('data-timeline-record-kind')){const focus=$('[data-timeline-focus-person]',form),explicit=$('[name="focus_relation_explicit"]',form);if(focus&&focus.dataset.personEdited!=='true'&&explicit?.value!=='1'){focus.value=event.target.value==='reflection'?'about':'direct';focus.dataset.defaultRelation=focus.value;saveDraft(form);}}
